<script setup lang="ts">
import {computed,onMounted,ref,useId,watch} from 'vue'
import '../styles/student-workspace.css'
import StudentHomeworkList from './StudentHomeworkList.vue'
import {studentHomeworkGroups} from '../student-homework-groups'
import {filterStudentHomework,homeworkDateLabel} from '../student-homework-filters'
import {scheduleApi} from '../schedules'
const today=ref(''),showHistory=ref(false),historyId=useId()
const query=new URLSearchParams(window.location.search)
const subject=ref(query.get('homeworkSubject')??''),historySubject=ref(query.get('historySubject')??''),period=ref(['all','today','tomorrow','week'].includes(query.get('homeworkDue')??'')?query.get('homeworkDue')!:'all')
showHistory.value=query.get('homeworkHistory')==='open'
watch([subject,historySubject,period,showHistory],()=>{const url=new URL(window.location.href);for(const [key,value] of Object.entries({homeworkSubject:subject.value,historySubject:historySubject.value,homeworkDue:period.value==='all'?'':period.value,homeworkHistory:showHistory.value?'open':''})){if(value)url.searchParams.set(key,value);else url.searchParams.delete(key)}window.history.replaceState(window.history.state,'',url)})
const loading=ref(false),error=ref(''),items=ref<any[]>([]),updated=ref(false)
const groups=computed(()=>studentHomeworkGroups(items.value,today.value))
const subjects=computed(()=>[...new Set(items.value.map(h=>h.course_name))].sort())
const current=computed(()=>filterStudentHomework(groups.value.current,subject.value,period.value,today.value))
const history=computed(()=>filterStudentHomework(groups.value.history,historySubject.value,'all',today.value))
const dayGroups=computed(()=>[...new Set(current.value.map(h=>h.due_on))].map(date=>({date,items:current.value.filter(h=>h.due_on===date)})))
async function load(){loading.value=true;error.value='';try{const r=await scheduleApi('student/homework');items.value=r.homework;today.value=r.today;updated.value=true;if(subject.value&&!subjects.value.includes(subject.value))subject.value='';if(historySubject.value&&!subjects.value.includes(historySubject.value))historySubject.value=''}catch(e){error.value=e instanceof Error?e.message:'Unable to load homework.'}finally{loading.value=false}}
function clearFilters(){subject.value='';period.value='all'}
onMounted(load)
</script>
<template><section class="student-homework" :aria-busy="loading"><header class="task-heading"><div><h2>Your homework</h2><p>Check what is due. Open a task for instructions.</p></div><div class="task-actions"><button type="button" class="task-button" :aria-expanded="showHistory" :aria-controls="historyId" @click="showHistory=!showHistory">{{showHistory?'Close history':'History'}} <span v-if="updated">({{groups.history.length}})</span></button><button type="button" class="task-button" :disabled="loading" @click="load">{{loading?'Refreshing…':'Refresh'}}</button></div></header><p v-if="error" class="task-error" role="alert">{{error}} <button type="button" class="task-link" :disabled="loading" @click="load">Try again</button></p><p v-if="!loading&&!error&&groups.overdue" class="task-reminder"><strong>{{groups.overdue}} overdue assignment(s)</strong><button type="button" class="task-link" @click="showHistory=true;historySubject=''">Review in history</button></p><div class="student-homework-layout" :class="{'history-open':showHistory}"><section class="current-tasks" aria-label="Current homework"><div class="task-section-heading"><h3>Current</h3><span>{{current.length}} tasks</span></div><div class="task-filters"><label>Due<select v-model="period" name="homework-due"><option value="all">All current days</option><option value="today">Today</option><option value="tomorrow">Tomorrow</option><option value="week">Next 7 days</option></select></label><label>Subject<select v-model="subject" name="homework-subject"><option value="">All subjects</option><option v-for="s in subjects" :key="s" :value="s">{{s}}</option></select></label></div><p v-if="loading&&!updated" class="task-empty" role="status">Loading your homework…</p><template v-for="group in dayGroups" :key="group.date"><div class="task-day"><h4>{{homeworkDateLabel(group.date,today)}}</h4><time :datetime="group.date">{{group.date}}</time></div><StudentHomeworkList :items="group.items" :today="today" /></template><div v-if="!loading&&!error&&!current.length" class="task-empty"><strong>{{groups.current.length?'No tasks match your filters.':'You have no current homework.'}}</strong><button v-if="groups.current.length" type="button" class="task-link" @click="clearFilters">Clear filters</button><p v-else>Past-due and reviewed tasks are in history.</p></div></section><aside v-if="showHistory" :id="historyId" class="task-history" aria-label="Homework history"><div class="task-section-heading"><h3>History</h3><span>{{history.length}} tasks</span></div><label class="history-filter">Subject<select v-model="historySubject" name="history-subject"><option value="">All subjects</option><option v-for="s in subjects" :key="s" :value="s">{{s}}</option></select></label><p class="history-description">Past-due and reviewed tasks. Unfinished work may still need attention.</p><StudentHomeworkList :items="history" :today="today" /><p v-if="!loading&&!error&&!history.length" class="task-empty">No history matches this subject.</p></aside></div><p v-if="updated" class="task-footnote">{{today}} (Nepal date). Status is recorded by your teacher.</p></section></template>
